import { Breadcrumb } from '@/react/components/ui/Breadcrumb'
import { TopBar } from '@/react/components/ui/TopBar'
// The bar over every console page: where you are, each step back a link, the page in ink, a namespace in mono.
const crumbs = [{ label: 'Overview', href: '#' }, { label: 'Namespaces', href: '#' }, { label: 'contracts', mono: true }]

export default function Product() {
  return (
    <TopBar className="border border-edge">
      <Breadcrumb items={crumbs} onNavigate={(_, e) => e.preventDefault()} />
    </TopBar>
  )
}

import { Breadcrumb as Trail } from '@/react/components/ui/Breadcrumb'
// The crumbs alone, as a breadcrumb anywhere: a long trail keeps every step back and truncates only the page.
const crumbs = [{ label: 'Overview', href: '#' }, { label: 'Sources', href: '#' }, { label: 'Acme drive', href: '#' }, { label: 'Quarterly planning notes for the platform team, final revision' }]

export default function Breadcrumb() {
  return (
    <div className="max-w-120">
      <Trail items={crumbs} onNavigate={(_, e) => e.preventDefault()} />
    </div>
  )
}

