import { html } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import styles from 'virtual:tw'

// TopBar.vue as <conare-top-bar>: the 48px bar over every console page (console2.css .v2-bar): sticky, a hairline
// under it, the page showing faintly through it (92% of the surface under an 8px blur), 12px text. Put a
// <conare-breadcrumb> in it; the `start` slot holds the phone's menu button, `end` what belongs to the whole console
// (setup progress, a loading mark), never the page's own actions. The host is the bar (a banner landmark, as Vue's
// <header> is), so classes on it land on the bar.

/**
 * @summary The bar over every console page, with where you are.
 * @slot - A <conare-breadcrumb>.
 * @slot start - The phone's menu button.
 * @slot end - What belongs to the whole console.
 */
export class TopBar extends DsElement {
	static styles = [DsElement.styles, styles]
	private internals = this.attachInternals()

	connectedCallback() {
		super.connectedCallback()
		this.internals.role = 'banner'
	}

	render() {
		return html`<slot name="start"></slot><slot></slot><slot name="end"></slot>`
	}
}

define('top-bar', TopBar)

/* The host is the bar (TopBar.vue's <header>), so a class on <conare-top-bar> lands on it as a class on <TopBar> does.
   A page's own reset (Tailwind's preflight: * { padding: 0; border: 0 solid }) beats a host's normal styles, so the
   padding and the hairline under it are important. */
:host { @apply sticky top-0 z-10 flex h-bar shrink-0 items-center gap-2 bg-bar text-meta leading-5 backdrop-blur-sm; @apply border-b! border-edge! px-4!; }

import { html } from 'lit'
import { Slash } from 'lucide'
import { DsElement, define } from '@/elements/lib/element'
import { icon } from '@/elements/lib/icon'
import styles from 'virtual:tw'

// Breadcrumb.vue as <conare-breadcrumb>: where you are (console2.css .v2-crumb): each step back a link in muted text
// that turns ink under the pointer, a 10px slash between, the page itself in ink and the only step that truncates.
// `mono` sets a namespace or an ID in Geist Mono. `items` is a JSON attribute or the property. A click on a step back
// fires `navigate` (detail.crumb, detail.event: call detail.event.preventDefault() to route it yourself).
export interface Crumb { label: string, href?: string, mono?: boolean }

/**
 * @summary Where you are: each step back a link, the page in ink.
 * @fires navigate - A step back was clicked (detail.crumb, detail.event).
 */
export class Breadcrumb extends DsElement {
	static styles = [DsElement.styles, styles]
	static properties = { items: { type: Array }, label: {} }

	/** The steps, the page last: { label, href?, mono? }. */
	items: Crumb[] = []
	/** The trail's name for assistive tech. */
	label = 'breadcrumb'

	render() {
		const last = this.items.length - 1
		return html`<nav data-ds="breadcrumb" class="flex min-w-0 flex-1 items-center gap-2 overflow-hidden text-meta leading-5" aria-label=${this.label}>${this.items.map((crumb, i) => html`${i > 0 ? icon(Slash, 'slash', { size: 10, strokeWidth: 1.5, class: 'shrink-0 text-fg-faint', attrs: { 'aria-hidden': 'true' } }) : ''}${i < last
			? html`<a href=${crumb.href ?? '#'} class=${['ds-crumb shrink-0', crumb.mono ? 'type-code-sm' : ''].join(' ')} @click=${(event: MouseEvent) => this.emit('navigate', { crumb, event })}>${crumb.label}</a>`
			: html`<span class=${['truncate text-fg', crumb.mono ? 'type-code-sm' : ''].join(' ')} aria-current="page">${crumb.label}</span>`}`)}</nav>`
	}
}

define('breadcrumb', Breadcrumb)

/* Breadcrumb.vue's <style>, as it is. */
.ds-crumb { color: var(--ds-color-fg-muted); transition: color var(--ds-duration-micro) var(--ds-easing-standard); }
@media (hover: hover) and (pointer: fine) { .ds-crumb:hover { color: var(--ds-color-fg); } }
.ds-crumb:focus-visible { outline: var(--ds-border-focus) solid var(--ds-color-edge-focus); outline-offset: 2px; }
